e_schema":"public","table_catalog":"postgres","privilege_type":"TRUNCATE","with_hierarchy":"NO"},{"grantee":"postgres","grantor":"postgres","table_name":"lm_drivers","is_grantable":"YES","table_schema":"public","table_catalog":"postgres","privilege_type":"UPDATE","with_hierarchy":"NO"},{"grantee":"service_role","grantor":"postgres","table_name":"lm_drivers","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"DELETE","with_hierarchy":"NO"},{"grantee":"service_role","grantor":"postgres","table_name":"lm_drivers","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"INSERT","with_hierarchy":"NO"},{"grantee":"service_role","grantor":"postgres","table_name":"lm_drivers","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"REFERENCES","with_hierarchy":"NO"},{"grantee":"service_role","grantor":"postgres","table_name":"lm_drivers","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"SELECT","with_hierarchy":"YES"},{"grantee":"service_role","grantor":"postgres","table_name":"lm_drivers","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"TRIGGER","with_hierarchy":"NO"},{"grantee":"service_role","grantor":"postgres","table_name":"lm_drivers","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"TRUNCATE","with_hierarchy":"NO"},{"grantee":"service_role","grantor":"postgres","table_name":"lm_drivers","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"UPDATE","with_hierarchy":"NO"}],"tables":[{"rls":true,"name":"lm_drivers"},{"rls":true,"name":"lm_driver_applications"}],"policies":[{"cmd":"SELECT","qual":"(auth_id = ( SELECT auth.uid() AS uid))","roles":["authenticated"],"tablename":"lm_driver_applications","permissive":"PERMISSIVE","policyname":"lm_driver_applications_own_read","schemaname":"public","with_check":null}],"functions":[{"acl":["postgres=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"name":"lm_approve_driver_application(uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.lm_approve_driver_application(p_application_id uuid, p_review_note text DEFAULT NULL::text)\n RETURNS lm_drivers\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare a public.lm_driver_applications%rowtype; p public.lm_profiles%rowtype; d public.lm_drivers%rowtype;\nbegin\n  if not public.lm_is_operator() then raise exception 'LUXE operator access required' using errcode='42501'; end if;\n  select * into a from public.lm_driver_applications where id=p_application_id for update;\n  if not found then raise exception 'Driver application not found'; end if;\n  if a.application_status='rejected' then raise exception 'Rejected application must be returned to review before approval'; end if;\n  if a.driver_license_status<>'verified' or a.insurance_status<>'verified' or a.background_status<>'verified' or a.vehicle_status<>'verified' then raise exception 'All driver, insurance, background, and vehicle checks must be verified before approval'; end if;\n  insert into public.lm_profiles(auth_id,role,full_name,phone,status) values(a.auth_id,'driver',a.full_name,a.phone,'active') on conflict(auth_id) do update set role='driver',full_name=excluded.full_name,phone=excluded.phone,status='active',updated_at=now() returning * into p;\n  insert into public.lm_drivers(profile_id,approval_status,on_duty,vehicle_class_id,vehicle_make,vehicle_model,vehicle_color,vehicle_plate,payouts_enabled)\n  values(p.id,'approved',false,a.vehicle_class_id,a.vehicle_make,a.vehicle_model,a.vehicle_color,a.vehicle_plate,false)\n  on conflict(profile_id) do update set approval_status='approved',on_duty=false,vehicle_class_id=excluded.vehicle_class_id,vehicle_make=excluded.vehicle_make,vehicle_model=excluded.vehicle_model,vehicle_color=excluded.vehicle_color,vehicle_plate=excluded.vehicle_plate,payouts_enabled=false,updated_at=now() returning * into d;\n  update public.lm_driver_applications set application_status='approved',review_note=left(nullif(trim(p_review_note),''),2000),reviewed_at=now(),reviewed_by=auth.uid(),updated_at=now() where id=a.id;\n  return d;\nend;$function$\n"},{"acl":["postgres=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"name":"lm_review_driver_application(uuid,text,text,text,text,text,text)","definition":"CREATE OR REPLACE FUNCTION public.lm_review_driver_application(p_application_id uuid, p_driver_license_status text, p_insurance_status text, p_background_status text, p_vehicle_status text, p_decision text DEFAULT 'under_review'::text, p_review_note text DEFAULT NULL::text)\n RETURNS lm_driver_applications\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare v public.lm_driver_applications%rowtype;\nbegin\n  if not public.lm_is_operator() then raise exception 'LUXE operator access required' using errcode='42501'; end if;\n  if p_driver_license_status not in ('pending','verified','rejected') or p_insurance_status not in ('pending','verified','rejected') or p_background_status not in ('pending','verified','rejected') or p_vehicle_status not in ('pending','verified','rejected') then raise exception 'Invalid verification status'; end if;\n  if p_decision not in ('under_review','rejected') then raise exception 'Review decision must be under_review or rejected'; end if;\n  update public.lm_driver_applications set driver_license_status=p_driver_license_status,insurance_status=p_insurance_status,background_status=p_background_status,vehicle_status=p_vehicle_status,application_status=p_decision,review_note=left(nullif(trim(p_review_note),''),2000),reviewed_at=now(),reviewed_by=auth.uid(),updated_at=now()\n  where id=p_application_id and application_status<>'approved' returning * into v;\n  if not found then raise exception 'Driver application not found or already approved'; end if;\n  return v;\nend;$function$\n"},{"acl":["postgres=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"name":"lm_submit_driver_application(text,text,text,text,text,text,text,text,integer,text,text,text)","definition":"CREATE OR REPLACE FUNCTION public.lm_submit_driver_application(p_full_name text, p_email text, p_phone text, p_city text, p_state_code text, p_vehicle_class_id text, p_vehicle_make text, p_vehicle_model text, p_vehicle_year integer, p_vehicle_color text, p_vehicle_plate text, p_applicant_note text DEFAULT NULL::text)\n RETURNS lm_driver_applications\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare v public.lm_driver_applications%rowtype;\nbegin\n  if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;\n  if coalesce(length(trim(p_full_name)),0)<2 then raise exception 'Full name is required'; end if;\n  if coalesce(length(trim(p_city)),0)<2 or coalesce(length(trim(p_state_code)),0)<2 then raise exception 'City and state are required'; end if;\n  if not exists(select 1 from public.lm_vehicle_classes where id=p_vehicle_class_id and is_active) then raise exception 'Vehicle class is unavailable'; end if;\n  if coalesce(length(trim(p_vehicle_make)),0)<2 or coalesce(length(trim(p_vehicle_model)),0)<1 or coalesce(length(trim(p_vehicle_plate)),0)<2 then raise exception 'Complete vehicle information is required'; end if;\n  if p_vehicle_year < extract(year from now())::int - 20 or p_vehicle_year > extract(year from now())::int + 1 then raise exception 'Vehicle year is outside the current LUXE review range'; end if;\n  insert into public.lm_driver_applications(auth_id,full_name,email,phone,city,state_code,vehicle_class_id,vehicle_make,vehicle_model,vehicle_year,vehicle_color,vehicle_plate,application_status,driver_license_status,insurance_status,background_status,vehicle_status,applicant_note,submitted_at,updated_at)\n  values(auth.uid(),trim(p_full_name),nullif(trim(p_email),''),nullif(trim(p_phone),''),trim(p_city),upper(trim(p_state_code)),p_vehicle_class_id,trim(p_vehicle_make),trim(p_vehicle_model),p_vehicle_year,trim(p_vehicle_color),upper(trim(p_vehicle_plate)),'submitted','pending','pending','pending','pending',left(nullif(trim(p_applicant_note),''),2000),now(),now())\n  on conflict(auth_id) do update set full_name=excluded.full_name,email=excluded.email,phone=excluded.phone,city=excluded.city,state_code=excluded.state_code,vehicle_class_id=excluded.vehicle_class_id,vehicle_make=excluded.vehicle_make,vehicle_model=excluded.vehicle_model,vehicle_year=excluded.vehicle_year,vehicle_color=excluded.vehicle_color,vehicle_plate=excluded.vehicle_plate,applicant_note=excluded.applicant_note,application_status=case when public.lm_driver_applications.application_status='approved' then 'approved' else 'submitted' end,driver_license_status=case when public.lm_driver_applications.application_status='approved' then public.lm_driver_applications.driver_license_status else 'pending' end,insurance_status=case when public.lm_driver_applications.application_status='approved' then public.lm_driver_applications.insurance_status else 'pending' end,background_status=case when public.lm_driver_applications.application_status='approved' then public.lm_driver_applications.background_status else 'pending' end,vehicle_status=case when public.lm_driver_applications.application_status='approved' then public.lm_driver_applications.vehicle_status else 'pending' end,submitted_at=case when public.lm_driver_applications.application_status='approved' then public.lm_driver_applications.submitted_at else now() end,updated_at=now()\n  returning * into v;\n  if v.application_status='approved' then raise exception 'Approved drivers must contact operations to change verified vehicle details'; end if;\n  return v;\nend;$function$\n"}]}$expected$::jsonb THEN RAISE EXCEPTION 'Unexpected Luxe boundary change'; END IF;
 IF EXISTS (SELECT 1 FROM unnest(ARRAY['anon','authenticated']) r CROSS JOIN unnest(ARRAY['public.lm_driver_applications','public.lm_drivers']) t CROSS JOIN unnest(ARRAY['TRUNCATE','REFERENCES','TRIGGER']) p WHERE has_table_privilege(r,t,p)) THEN RAISE EXCEPTION 'Unwanted effective privilege remains'; END IF;
END $verify$;